/** An inline glyph drawn in currentColor; size in px. */
export function glyph(name, size = 18) {
  return html`<svg class="gl" viewBox="0 0 24 24" width=${size} height=${size} aria-hidden="true"><path fill="currentColor" d=${MC_GLYPHS[name]}></path></svg>`;
}
